const input = $input.first()?.json || {};
const rawValue = input.output || input.text || input.content || '';
const raw = typeof rawValue === 'string' ? rawValue : JSON.stringify(rawValue);
let parsed;
try {
  parsed = JSON.parse(raw.replace(/```json/g, '').replace(/```/g, '').trim());
} catch {
  parsed = { reply: raw.trim() };
}

const trigger = $('When Executed by Another Workflow').first()?.json || {};
const businessName = String($('Format Context').first()?.json?.business_name || 'our company');

let reply = typeof parsed.reply === 'string' ? parsed.reply : String(raw).trim();

// Guard: if the AI echoed unresolved template syntax from context, fall back to a greeting.
if (/{{|\$json|\$node|\$env/.test(reply)) {
  reply = 'Good afternoon! You\'re speaking with ' + businessName + '. How can I help you today?';
}

const cleanFacts = (Array.isArray(parsed.facts_extracted) ? parsed.facts_extracted : [])
  .map(f => ({
    key: String((f && (f.key || f.fact_key)) || ''),
    value: String((f && (f.value || f.fact_value)) || ''),
    confidence: f && f.confidence != null ? f.confidence : 1
  }))
  .filter(f => f.key && f.value && !['null', 'undefined', ''].includes(f.key.toLowerCase()));

return [{
  json: {
    reply,
    facts_extracted: cleanFacts,
    intent: typeof parsed.intent === 'string' ? parsed.intent : 'general_inquiry',
    lead_stage: typeof parsed.lead_stage === 'string' ? parsed.lead_stage : 'qualifying',
    sentiment: typeof parsed.sentiment === 'string' ? parsed.sentiment : 'neutral',
    escalate: !!parsed.escalate,
    escalation_reason: typeof parsed.escalation_reason === 'string' ? parsed.escalation_reason : '',
    conversation_id: trigger.conversation_id || '',
    contact_id: trigger.contact_id || ''
  }
}];

try { const ctx = $input.first()?.json || {}; const facts = Array.isArray(ctx.customer_facts) ? ctx.customer_facts.filter(f => f && f.fact_key && f.fact_value !== null && f.fact_value !== undefined && f.fact_key !== 'null') : []; const factName = facts.find(f => f.fact_key === 'customer_name')?.fact_value || ''; const businessName = ctx.business_name || 'our company'; const customerName = (ctx.customer?.name && ctx.customer.name !== 'Unknown' ? ctx.customer.name : factName) || 'Unknown'; let prompt = `AUTHORITATIVE BUSINESS IDENTITY: ${businessName}
Never output unresolved template expressions such as {{ $json.business_name }}. If asked about the business, answer using the business identity above.
`; if (customerName !== 'Unknown') prompt += `AUTHORITATIVE CUSTOMER NAME: ${customerName}
If asked the customer name, answer it directly.
`; if (ctx.customer?.phone) prompt += `CUSTOMER PHONE: ${ctx.customer.phone}
`; if (facts.length) { prompt += '
CUSTOMER FACTS:
'; for (const f of facts) prompt += `- ${f.fact_key}: ${f.fact_value}
`; } if (Array.isArray(ctx.knowledge) && ctx.knowledge.length) { prompt += '
AUTHORITATIVE KNOWLEDGE:
'; for (const kb of ctx.knowledge.slice(0, 8)) prompt += `- ${kb.chunk_text}
`; } if (Array.isArray(ctx.products) && ctx.products.length) { prompt += '
PRODUCTS:
'; for (const p of ctx.products.slice(0, 20)) prompt += `- ${p.name}: ${p.price} ${p.currency}
`; } const recent = Array.isArray(ctx.recent_messages) ? ctx.recent_messages.slice(-6) : []; const history = recent.map(m => `${m.direction === 'in' || m.direction === 'incoming' ? 'Customer' : 'Assistant'}: ${m.text_body}`).join('
') || 'No previous messages.'; return [{ json: { formattedPrompt: prompt, business_name: businessName, business_timezone: ctx.business_timezone || 'America/Jamaica', conversationHistory: history, customerFacts: facts, customerName, currentMessage: ctx.current_message?.text || '' } }]; } catch(e) { return [{ json: { formattedPrompt: 'AUTHORITATIVE BUSINESS IDENTITY: our company
No context available.', business_name: 'our company', conversationHistory: 'No previous messages.', customerFacts: [], customerName: 'Unknown' } }]; }

